// Illustrative decorator (needs experimentalDecorators):
//   class Greeter { @log greet(name: string) { return 'hi ' + name; } }
// Equivalent behavior the decorator installs, shown plainly so it runs:
function wrapWithLog(fn: (...a: any[]) => any, key: string) {
  return function (this: any, ...args: any[]) {
    console.log('call', key, 'with', args.join(','));
    return fn.apply(this, args);
  };
}

const greet = wrapWithLog((name: string) => 'hi ' + name, 'greet');
console.log(greet('Ada'));

