solution.code:
function makeMemoized(fn: (n: number) => number) {
  const cache = new Map<number, number>();
  return (n: number): number => {
    if (cache.has(n)) return cache.get(n)!;
    const result = fn(n);
    cache.set(n, result);
    return result;
  };
}

let calls = 0;
const square = makeMemoized((n: number) => { calls++; return n * n; });
console.log(square(4), square(4), 'calls=' + calls);

