function measure(_target: any, propertyKey: string, descriptor: PropertyDescriptor): void {
  const original = descriptor.value;
  descriptor.value = function (this: any, ...args: any[]) {
    const start = Date.now();
    const result = original.apply(this, args);
    console.log(`${propertyKey} took ${Date.now() - start}ms`);
    return result;
  };
}

class Report {
  @measure
  build(rows: number): number {
    let sum = 0;
    for (let i = 0; i < rows; i++) sum += i;
    return sum;
  }
}

console.log(new Report().build(1000));
